const header='<a class="skip" href="#main">Skip to content</a><header class="header"><div class="container header-inner"><a class="header-logo" href="index.html" aria-label="ELEVATE home"><img src="assets/elevate-black.svg" alt="ELEVATE"></a>'+desktopNavigation+'<button class="mobile-menu secondary" aria-expanded="false" aria-controls="primary-nav" aria-label="Open navigation">Menu</button><nav class="nav" id="primary-nav" aria-label="Mobile navigation">'+navigationMarkup+'</nav><a class="header-contact" href="contact.html">Contact Us</a></div></header>';
